// A map connection is one campaign jump. Network topology is independent of
// search, camera rotation, and visibility of the lane layer.
export function buildLanes(nodes,provided){const ids=new Set(nodes.map(n=>n.id)),pairs=new Map();const add=(a,b)=>{if(a===b||!ids.has(a)||!ids.has(b))return;const edge=[a,b].sort();pairs.set(JSON.stringify(edge),edge)};
 if(Array.isArray(provided)){for(const edge of provided)if(Array.isArray(edge)&&edge.length===2)add(edge[0],edge[1]);}
 else for(const a of nodes){const near=nodes.filter(b=>a.id!==b.id).sort((b,c)=>Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z)-Math.hypot(a.x-c.x,a.y-c.y,a.z-c.z)||b.id.localeCompare(c.id)).slice(0,2);for(const b of near)add(a.id,b.id)}
 return [...pairs.values()].sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)));
}
export function findLanePath(nodes,edges,from,to){const available=new Set(nodes.map(n=>n.id));if(!available.has(from)||!available.has(to))return null;const graph=new Map([...available].map(id=>[id,[]]));for(const [a,b]of edges)if(available.has(a)&&available.has(b)){graph.get(a).push(b);graph.get(b).push(a)}const parent=new Map([[from,null]]),queue=[from];for(let i=0;i<queue.length;i++){const a=queue[i];if(a===to){const path=[];for(let n=to;n!==null;n=parent.get(n))path.push(n);return path.reverse()}for(const b of graph.get(a).sort())if(!parent.has(b)){parent.set(b,a);queue.push(b)}}return null;}
// Bidirectional gates sit on a system's outer boundary, along the real 3D
// vector to the neighboring system. They are derived from the canonical lanes.
export function buildSystemGates(system,nodes,edges,radius){const byId=new Map(nodes.map(n=>[n.id,n])),peers=new Set();for(const [a,b]of edges){if(a===system.id&&byId.has(b))peers.add(b);if(b===system.id&&byId.has(a))peers.add(a)}return [...peers].sort().map(id=>{const peer=byId.get(id);let dx=peer.x-system.x,dy=peer.y-system.y,dz=peer.z-system.z,len=Math.hypot(dx,dy,dz),coincident=len<1e-9;if(coincident){let seed=0;for(const c of [system.id,id].sort().join(':'))seed=(seed*31+c.charCodeAt(0))>>>0;const a=(seed%6283)/1000,sign=system.id<id?1:-1;dx=Math.cos(a)*sign;dy=Math.sin(a)*sign;dz=0;len=1;}const direction={x:dx/len,y:dy/len,z:dz/len},bearing=(Math.atan2(dx,-dy)*180/Math.PI+360)%360,elevation=Math.atan2(dz,Math.hypot(dx,dy))*180/Math.PI;return {id:'drift-gate:'+encodeURIComponent(system.id)+':'+encodeURIComponent(id),name:peer.name+' Gate',type:'driftGate',parent:system.id,parentEntity:system.type,linkTo:id,direction,x:direction.x*radius,y:direction.y*radius,z:direction.z*radius,isHidden:false,generated:true,attributes:{connection:peer.name,function:'Bidirectional lane entrance / exit',bearing:bearing.toFixed(1)+'°',elevation:(elevation>=0?'+':'')+elevation.toFixed(1)+'°',travelTime:'7 days to '+peer.name,arrivalGate:system.name+' Gate in '+peer.name,directionSource:coincident?'Co-located sector coordinates · schematic direction':'Direction of the connected system in sector space'}};});}
